async function authSubmit(e:React.FormEvent){e.preventDefault();if(!isSupabaseConfigured){toast.error(getSupabaseSetupMessage(),{duration:10000});return}Busy(true);try{let r;if(mode==="register")r=await supabase.auth.signUp({email,password});else if(mode==="forgot")r=await supabase.auth.resetPasswordForEmail(email,{redirectTo:location.origin});else r=await supabase.auth.signInWithPassword({email,password});if(r.error)throw r.error;if(mode==="forgot")toast.success("Se o e-mail estiver cadastrado, enviaremos as instruções.");else if(mode==="register"&&!r.data.session)toast.success("Cadastro criado! Confirme seu e-mail para entrar.")}catch(e:any){const msg=String(e?.message||"");const lower=msg.toLowerCase();if(lower.includes("failed to fetch")||lower.includes("networkerror")||lower.includes("fetch failed")){toast.error("Não foi possível conectar ao Supabase. Confira sua internet, a URL VITE_SUPABASE_URL e a chave VITE_SUPABASE_ANON_KEY no arquivo .env. Depois reinicie o servidor com Ctrl+C e npm run dev.",{duration:12000});console.error("Falha de conexão no cadastro:",e)}else if(msg==="Invalid login credentials")toast.error("E-mail ou senha incorretos.");else if(lower.includes("email not confirmed"))toast.error("Confirme seu e-mail pelo link enviado antes de entrar.");else if(lower.includes("user already registered"))toast.error("Este e-mail já possui cadastro. Volte ao login ou use Esqueci minha senha.");else toast.error(msg||"Não foi possível concluir o cadastro. Confira a conexão e tente novamente.")}finally{Busy(false)}}
