async function saveSale(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget),p=products.find(x=>x.id===String(f.get("produto_id")));if(!p)return toast.error("Selecione um produto.");const qty=Number(f.get("quantidade")),discount=Number(f.get("desconto")||0),gross=qty*Number(p.preco_venda),payment=String(f.get("forma_pagamento")),client=String(f.get("cliente")||"").trim();if(payment==="Fiado"&&!client)return toast.error("Informe o nome do cliente para registrar uma venda fiada.");const oldSale=saleModal&&typeof saleModal==="object"?saleModal as Sale:null;const available=p.estoque+(oldSale&&oldSale.produto_id===p.id?Number(oldSale.quantidade):0);if(qty<1||qty>available||discount<0||discount>gross)return toast.error("Quantidade ou desconto inválido; confira o estoque disponível.");if(oldSale){if(oldSale.forma_pagamento==="Fiado"||payment==="Fiado"){toast.error("Para evitar divergências entre a venda e as contas a receber, vendas fiadas não podem ser editadas por esta tela. Ajuste a dívida em Contas a Receber.");return}const dataVenda=new Date(String(f.get("data_venda"))).toISOString();const upd=await supabase.from("vendas").update({produto_id:p.id,quantidade:qty,desconto:discount,forma_pagamento:payment,cliente:client||null,data_venda:dataVenda,valor_bruto:gross,valor_liquido:gross-discount,custo_total:qty*Number(p.preco_custo)}).eq("id",oldSale.id);if(upd.error){toast.error(upd.error.message);return}SM(false);toast.success("Venda atualizada.");await load();return}let debtorId=null;if(payment==="Fiado"){let dr=await supabase.from("devedores").select("id").eq("user_id",session.user.id).ilike("nome",client).limit(1).maybeSingle();if(dr.error)return toast.error("Não foi possível localizar o cliente: "+dr.error.message);if(dr.data)debtorId=dr.data.id;else{dr=await supabase.from("devedores").insert({user_id:session.user.id,nome:client}).select("id").single();if(dr.error)return toast.error("Não foi possível cadastrar o cliente: "+dr.error.message);debtorId=dr.data.id}}const dataVenda=new Date(String(f.get("data_venda"))).toISOString();const r=await supabase.from("vendas").insert({user_id:session.user.id,produto_id:p.id,quantidade:qty,desconto:discount,forma_pagamento:payment,cliente:client||null,data_venda:dataVenda,valor_bruto:gross,valor_liquido:gross-discount,custo_total:qty*Number(p.preco_custo)});if(r.error){toast.error(r.error.message);return}if(payment==="Fiado"){const vencimento=new Date(dataVenda);vencimento.setDate(vencimento.getDate()+30);const debt=await supabase.from("dividas").insert({user_id:session.user.id,devedor_id:debtorId,descricao:"Venda fiada: "+p.nome+" ("+qty+" un.)",valor_original:gross-discount,saldo:gross-discount,data_vencimento:vencimento.toISOString().slice(0,10),status:"aberta"});if(debt.error){toast.error("A venda foi registrada, mas não foi possível criar a dívida: "+debt.error.message);SM(false);load();return}}SM(false);toast.success(payment==="Fiado"?"Venda fiada registrada e dívida adicionada.":"Venda registrada e estoque atualizado.");await load()}
