async function savePayment(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const debt=paymentModal;if(!debt)return;const f=new FormData(e.currentTarget),raw=String(f.get("valor")||"0").trim().replace(",", "."),valor=Number(raw),observacao=String(f.get("observacao")||"");if(!Number.isFinite(valor)||valor<=0||valor>Number(debt.saldo))return toast.error("Informe um valor maior que zero e não superior ao saldo pendente.");const r=await supabase.rpc("registrar_pagamento_divida",{p_divida_id:debt.id,p_valor:valor,p_observacao:observacao});if(r.error){toast.error(r.error.message);return}PaymentModal(null);toast.success("Pagamento registrado com sucesso.");await load()}
async function saveRecord(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const r=recordModal;if(!r)return;const f=new FormData(e.currentTarget);let result:any;if(r.type==="cliente"){result=await supabase.from("devedores").update({nome:String(f.get("nome")).trim(),telefone:String(f.get("telefone")||""),endereco:String(f.get("endereco")||""),observacoes:String(f.get("observacoes")||"")}).eq("id",r.item.id)}else if(r.type==="divida"){const original=Number(f.get("valor_original")),paid=Number(r.item.valor_original)-Number(r.item.saldo),saldo=original-paid;if(original<=0||saldo<0)return toast.error("O valor não pode ser menor que o valor já recebido.");result=await supabase.from("dividas").update({devedor_id:String(f.get("devedor_id")),descricao:String(f.get("descricao")).trim(),valor_original:original,saldo,data_vencimento:String(f.get("vencimento")),status:saldo<=0?"quitada":"aberta"}).eq("id",r.item.id)}else{const valor=Number(f.get("valor")),delta=valor-Number(r.item.valor),debt=debts.find(d=>d.id===r.item.divida_id);if(valor<=0)return toast.error("Informe um valor maior que zero.");if(!debt)return toast.error("Dívida vinculada não encontrada.");if(Number(debt.saldo)+Number(r.item.valor)-valor<0)return toast.error("O valor excede o saldo da dívida.");result=await supabase.from("pagamentos_dividas").update({valor,observacao:String(f.get("observacao")||"")}).eq("id",r.item.id);if(!result.error){const saldo=Number(debt.saldo)-delta;const upd=await supabase.from("dividas").update({saldo,status:saldo<=0?"quitada":"aberta"}).eq("id",debt.id);if(upd.error)return toast.error("Pagamento atualizado, mas o saldo não foi atualizado: "+upd.error.message)}}if(result?.error){toast.error(result.error.message);return}RecordModal(null);toast.success("Registro atualizado.");await load()}
async function deleteRecord(type:string,item:any){ConfirmModal({title:type==="cliente"?"Excluir cliente?":type==="divida"?"Excluir dívida?":"Excluir pagamento?",description:type==="cliente"?"Deseja realmente excluir este cliente? Esta ação não pode ser desfeita.":type==="divida"?"Deseja excluir esta dívida? Esta ação não pode ser desfeita.":"Deseja excluir este pagamento recebido? O saldo da dívida será atualizado.",confirmLabel:"Sim, excluir",action:async()=>{if(type==="cliente"){if(debts.some(d=>d.devedor_id===item.id)){toast.error("Não é possível excluir um cliente que possui dívidas vinculadas.");return}const r=await supabase.from("devedores").delete().eq("id",item.id);if(r.error)toast.error(r.error.message);else toast.success("Cliente excluído.")}else if(type==="divida"){if(debtPayments.some(p=>p.divida_id===item.id)){toast.error("Exclua primeiro os pagamentos vinculados a esta dívida.");return}const r=await supabase.from("dividas").delete().eq("id",item.id);if(r.error)toast.error(r.error.message);else toast.success("Dívida excluída.")}else{const debt=debts.find(d=>d.id===item.divida_id);const r=await supabase.from("pagamentos_dividas").delete().eq("id",item.id);if(r.error){toast.error(r.error.message);return}if(debt){const saldo=Number(debt.saldo)+Number(item.valor);const upd=await supabase.from("dividas").update({saldo,status:saldo<=0?"quitada":"aberta"}).eq("id",debt.id);if(upd.error){toast.error("Pagamento excluído; confira o saldo da dívida: "+upd.error.message);load();return}}toast.success("Pagamento excluído e saldo recalculado.")}load()}})}
